func (x *Session) ConnectJobFinished(cb *func(Session, uintptr, uintptr)) uint32 {
	cbPtr := uintptr(unsafe.Pointer(cb))
	if cbRefPtr, ok := glib.GetCallback(cbPtr); ok {
		return gobject.SignalConnect(x.GoPointer(), "job-finished", cbRefPtr)
	}

	fcb := func(clsPtr uintptr, ObjectVarp uintptr, P0Varp uintptr) {
		fa := Session{}
		fa.Ptr = clsPtr
		cbFn := *cb

		cbFn(fa, ObjectVarp, P0Varp)

	}
	cbRefPtr := purego.NewCallback(fcb)
	glib.SaveCallback(cbPtr, cbRefPtr)
	return gobject.SignalConnect(x.GoPointer(), "job-finished", cbRefPtr)
}

func (x *Session) ConnectJobStarted(cb *func(Session, uintptr)) uint32 {
	cbPtr := uintptr(unsafe.Pointer(cb))
	if cbRefPtr, ok := glib.GetCallback(cbPtr); ok {
		return gobject.SignalConnect(x.GoPointer(), "job-started", cbRefPtr)
	}

	fcb := func(clsPtr uintptr, ObjectVarp uintptr) {
		fa := Session{}
		fa.Ptr = clsPtr
		cbFn := *cb

		cbFn(fa, ObjectVarp)

	}
	cbRefPtr := purego.NewCallback(fcb)
	glib.SaveCallback(cbPtr, cbRefPtr)
	return gobject.SignalConnect(x.GoPointer(), "job-started", cbRefPtr)
}

// This purpose of this signal is to propagate a server-issued alert
// message from @service to a user interface.  The @type hints at the
// severity of the alert message.
func (x *Session) ConnectUserAlert(cb *func(Session, uintptr, SessionAlertType, string)) uint32 {
	cbPtr := uintptr(unsafe.Pointer(cb))
	if cbRefPtr, ok := glib.GetCallback(cbPtr); ok {
		return gobject.SignalConnect(x.GoPointer(), "user-alert", cbRefPtr)
	}

	fcb := func(clsPtr uintptr, ServiceVarp uintptr, TypeVarp SessionAlertType, MessageVarp string) {
		fa := Session{}
		fa.Ptr = clsPtr
		cbFn := *cb

		cbFn(fa, ServiceVarp, TypeVarp, MessageVarp)

	}
	cbRefPtr := purego.NewCallback(fcb)
	glib.SaveCallback(cbPtr, cbRefPtr)
	return gobject.SignalConnect(x.GoPointer(), "user-alert", cbRefPtr)
}

